<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{EWallet,Role,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AuthController extends Controller { public function register(Request $r){$data=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|unique:users,email','password'=>'required|string|min:8','role'=>'nullable|string|exists:roles,name']); $user=DB::transaction(function()use($data){$user=User::create(['name'=>$data['name'],'email'=>$data['email'],'password'=>$data['password'],'role_id'=>Role::where('name',$data['role']??'USER')->value('id')]); EWallet::create(['user_id'=>$user->id]); return $user;}); return $this->tokenResponse($user,201); } public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string']); $user=User::where('email',$data['email'])->first(); if(!$user || !password_verify($data['password'],$user->password)){return response()->json(['message'=>'Email atau password salah'],422);} return $this->tokenResponse($user); } public function logout(Request $r){$r->user()->currentAccessToken()?->delete(); return response()->json(['message'=>'Berhasil logout']);} private function tokenResponse(User $u,int $code=200){$token=$u->createToken('titip-kilat-device')->plainTextToken; return response()->json(['user'=>$u->load('role','wallet'),'token'=>$token],$code); } }
